1	/**
2	 * Scoped to this molecule's own contract per testing.md: the AC-1/AC-5 branch logic and the
3	 * roving-tabindex invariant that this component alone is responsible for proving. Keyboard-focus
4	 * movement and pagination-window interaction are exercised in index.stories.tsx's `play`
5	 * functions instead — both are "user-facing interaction in a single component," which
6	 * testing.md routes to Storybook `play`, not Vitest.
7	 *
8	 * ZimmColourSwatch is left real (not mocked): composition is part of the contract under test —
9	 * this suite proves how many colours the molecule chooses to render and which one it marks
10	 * selected, not how a swatch itself looks (that is ZimmColourSwatch's own suite's job).
11	 *
12	 * Every render is wrapped three ways:
13	 *   - `ChakraProvider theme={theme}` — the real theme, not Chakra's default. Without it,
14	 *     `useMultiStyleConfig` for both this recipe and the atom's own resolve against a theme with
15	 *     no such keys registered — same reasoning as zimmProductMeta/index.test.tsx's own note.
16	 *   - `MemoryRouter` — ZimmColourSwatch can render a react-router `Link`, which throws outside one.
17	 *   - `IntlProvider` — this component calls `useIntl()` directly, which throws outside one
18	 *     (react-intl's `invariantIntlContext`).
19	 *
20	 * ZimmIcon is mocked at the smallest surface — the known, documented Vitest gap (it pulls in the
21	 * base SFCC icons barrel, which has a top-level side effect that fails under Vitest's SVG
22	 * transform; see testing.md). Mocked via the same relative specifier index.tsx itself imports,
23	 * so there is no cross-specifier module-resolution question to reason about.
24	 */
25	import React from 'react';
26	import { describe, test, expect, vi } from 'vitest';
27	import { render, screen } from '@testing-library/react';
28	import userEvent from '@testing-library/user-event';
29	import { ChakraProvider } from '@chakra-ui/react';
30	import { MemoryRouter } from 'react-router-dom';
31	import { IntlProvider } from 'react-intl';
32	import theme from 'app/theme';
33	import { ZimmColourSwatchGroup } from './index';
34	import type { ZimmColourSwatchValue } from './index';
35	
36	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
37	
38	const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;
39	
40	const BAY_BLUE: ZimmColourSwatchValue = {
41	  value: 'BAYBL',
42	  name: 'Bay Blue',
43	  href: '/p.html?color=BAYBL',
44	  imageUrl: IMAGE('bay-blue'),
45	};
46	const IVORY: ZimmColourSwatchValue = {
47	  value: 'IVORY',
48	  name: 'Ivory',
49	  href: '/p.html?color=IVORY',
50	  imageUrl: IMAGE('ivory'),
51	};
52	const BLACK: ZimmColourSwatchValue = {
53	  value: 'BLACK',
54	  name: 'Black',
55	  href: '/p.html?color=BLACK',
56	  imageUrl: IMAGE('black'),
57	};
58	/** No `imageUrl` — exercises AC 5's filter. */
59	const ROSE_UNPOPULATED: ZimmColourSwatchValue = { value: 'ROSE', name: 'Rose Pink', href: '/p.html?color=ROSE' };
60	const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };
61	
62	const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
63	  render(
64	    <ChakraProvider theme={theme}>
65	      <IntlProvider locale="en-AU" defaultLocale="en-AU">
66	        <MemoryRouter>
67	          <ZimmColourSwatchGroup label="Colour" values={[BAY_BLUE, IVORY, BLACK]} {...props} />
68	        </MemoryRouter>
69	      </IntlProvider>
70	    </ChakraProvider>,
71	  );
72	
73	describe('ZimmColourSwatchGroup', () => {
74	  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
75	    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });
76	    expect(screen.queryAllByRole('radio')).toHaveLength(0);
77	    expect(screen.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
78	  });
79	
80	  test('renders one radio swatch per populated colour', () => {
81	    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
82	    expect(screen.getAllByRole('radio')).toHaveLength(3);
83	  });
84	
85	  test('marks exactly the swatch matching selectedValue as checked', () => {
86	    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
87	    const checked = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('aria-checked') === 'true');
88	    expect(checked).toHaveLength(1);
89	    expect(checked[0]).toHaveAccessibleName('Ivory');
90	  });
91	
92	  test('AC 5: filters out colours whose index image is not populated', () => {
93	    const { container } = renderGroup({ values: [BAY_BLUE, IVORY, BLACK, ROSE_UNPOPULATED, GOLD_UNPOPULATED] });
94	    expect(screen.getAllByRole('radio')).toHaveLength(3);
95	    expect(container.textContent).not.toContain('Rose Pink');
96	    expect(container.textContent).not.toContain('Gold');
97	  });
98	
99	  test('AC 5 filters on image population only, never a stock/orderability-like field', () => {
100	    // This component's own prop type carries no stock field at all — the extra property below
101	    // proves the filter cannot be keying on one, since there is nowhere in the type for it to
102	    // come from other than this deliberately-bolted-on test fixture.
103	    const valueWithExtraField: ZimmColourSwatchValue & { orderable: boolean } = { ...BAY_BLUE, orderable: false };
104	    renderGroup({ values: [valueWithExtraField, IVORY] });
105	    expect(screen.getByRole('radio', { name: 'Bay Blue' })).toBeInTheDocument();
106	  });
107	
108	  test('collapses to the label-only branch when only one of several colours is populated', () => {
109	    renderGroup({
110	      selectedName: 'Bay Blue',
111	      selectedValue: 'BAYBL',
112	      values: [BAY_BLUE, ROSE_UNPOPULATED, GOLD_UNPOPULATED],
113	    });
114	    expect(screen.queryAllByRole('radio')).toHaveLength(0);
115	  });
116	
117	  test('keeps exactly one swatch in the roving tab order at a time', () => {
118	    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
119	    const tabbable = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('tabindex') === '0');
120	    expect(tabbable).toHaveLength(1);
121	  });
122	
123	  test('resolves its recipe under a ChakraProvider — registered, not silently inherited', () => {
124	    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
125	    // The only detection anywhere for this recipe losing its entry in theme/components/index.ts
126	    // — same reasoning as zimmProductMeta/index.test.tsx's own equivalent test. Measured as the
127	    // literal var() declaration, not a resolved px value: jsdom's getComputedStyle does not
128	    // substitute a custom property (see zimmColourSwatch/index.test.tsx's own note on this).
129	    const styles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
130	    expect(styles.gap).toBe('var(--zimm-scale-xs)');
131	  });
132	
133	  test('mounts directly on the page containing the actual selection, not always page 1 (pagination regression)', () => {
134	    // 6 populated colours, selection is the 6th (index 5) — beyond the first 4-wide page. Before
135	    // the fix, `pageStart` always started at 0 regardless of where the selection sat, so this
136	    // exact shape rendered page 1 (indices 0-3) with zero items aria-checked and zero items
137	    // tabbable, since the selected colour was never part of the rendered window.
138	    const SIXTH_COLOUR: ZimmColourSwatchValue = {
139	      value: 'NAVY',
140	      name: 'Navy',
141	      href: '/p.html?color=NAVY',
142	      imageUrl: IMAGE('navy'),
143	    };
144	    const sixColours: ZimmColourSwatchValue[] = [
145	      BAY_BLUE,
146	      IVORY,
147	      BLACK,
148	      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
149	      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
150	      SIXTH_COLOUR,
151	    ];
152	
153	    // No interaction of any kind above this line — this asserts the component's very first render.
154	    renderGroup({ selectedName: SIXTH_COLOUR.name, selectedValue: SIXTH_COLOUR.value, values: sixColours });
155	
156	    const radios = screen.getAllByRole('radio');
157	    const checkedRadios = radios.filter((radio) => radio.getAttribute('aria-checked') === 'true');
158	    const tabbableRadios = radios.filter((radio) => radio.getAttribute('tabindex') === '0');
159	
160	    expect(checkedRadios).toHaveLength(1);
161	    expect(checkedRadios[0]).toHaveAttribute('aria-checked', 'true');
162	    expect(checkedRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);
163	
164	    expect(tabbableRadios).toHaveLength(1);
165	    expect(tabbableRadios[0]).toHaveAttribute('tabindex', '0');
166	    expect(tabbableRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);
167	  });
168	
169	  test('reserves a fixed page-width footprint once paginated, so the row does not resize on a shorter final page (layout regression)', async () => {
170	    // 6 populated colours -> paginated (> SWATCHES_PER_PAGE = 4): page 1 renders a full 4-swatch
171	    // window, the final page only the remaining 2. Before the fix, `swatches` was a plain `100%`
172	    // of `root`, and `root` itself has no explicit width — it auto-fits to its widest child,
173	    // which is `swatches` itself. That circular relationship meant the rendered footprint tracked
174	    // how many items the current window actually held, so `root` (and `label` above it, itself
175	    // 100% of that same `root`) visibly resized between pages — confirmed directly in a running
176	    // Storybook, where the pagination chevrons jumped position between the two pages of the
177	    // `Paginated` story.
178	    const sixColours: ZimmColourSwatchValue[] = [
179	      BAY_BLUE,
180	      IVORY,
181	      BLACK,
182	      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
183	      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
184	      { value: 'NAVY', name: 'Navy', href: '/p.html?color=NAVY', imageUrl: IMAGE('navy') },
185	    ];
186	
187	    renderGroup({ selectedName: BAY_BLUE.name, selectedValue: BAY_BLUE.value, values: sixColours });
188	    expect(screen.getAllByRole('radio')).toHaveLength(4);
189	
190	    // jsdom has no real layout engine — getBoundingClientRect() reads 0 for every element
191	    // regardless of whether the fix is applied, which would make a before/after comparison pass
192	    // even against the pre-fix code (a false negative that proves nothing). getComputedStyle
193	    // *does* reliably read back the literal declared CSS value for a Chakra/emotion-authored
194	    // style in this codebase's jsdom setup — the same technique the "resolves its recipe under a
195	    // ChakraProvider" test above already relies on for `gap`.
196	    const widthBefore = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;
197	
198	    // Pinned to the specific reserved-footprint expression — and explicitly not the old `100%` —
199	    // rather than just compared against the post-click reading. A plain `100%` is ALSO textually
200	    // identical to itself before and after clicking "next" (the literal declared string never
201	    // changes; only what it resolves against would, which jsdom cannot compute). Without this,
202	    // a same-value-both-times check alone would pass against the pre-fix code too and would not
203	    // actually catch the regression.
204	    const PAGE_SIZE = 4;
205	    const expectedWidth = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;
206	    expect(widthBefore).toBe(expectedWidth);
207	    expect(widthBefore).not.toBe('100%');
208	
209	    await userEvent.click(screen.getByRole('button', { name: /next colours/i }));
210	
211	    // Now on the final, partial (2-item) page.
212	    expect(screen.getAllByRole('radio')).toHaveLength(2);
213	
214	    const widthAfter = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;
215	    expect(widthAfter).toBe(widthBefore);
216	    expect(widthAfter).not.toBe('100%');
217	  });
218	
219	  test('caps root to the reserved 4-swatch footprint so a long colour name has something to truncate against (layout regression)', () => {
220	    // Before the fix, `root` had no width of its own at all — deliberate, so a short,
221	    // non-paginated row still sizes naturally to its actual content (see the `swatches` part's own
222	    // comment) — which meant it also had no ceiling for `labelName`'s truncation CSS to truncate
223	    // against. Confirmed directly via real Chromium/Storybook rendering: a 70-character colour
224	    // name grew `root` to ~390px (its own widest-child shrink-to-fit width) with the name
225	    // rendering in full — `getComputedStyle(root).maxWidth` read back literally `none` in that
226	    // broken state. Capping `root.maxWidth` to the same reserved 4-swatch footprint `swatches`
227	    // already reserves once paginated fixes this unconditionally, not just when paginated — see
228	    // the next test for the paginated case.
229	    const LONG_NAME = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
230	    renderGroup({ selectedName: LONG_NAME, selectedValue: 'BAYBL' });
231	
232	    const rootStyles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
233	    const PAGE_SIZE = 4;
234	    const expectedMaxWidth = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;
235	    expect(rootStyles.maxWidth).toBe(expectedMaxWidth);
236	    expect(rootStyles.maxWidth).not.toBe('none');
237	  });
238	
239	  test('keeps the same root maxWidth cap once paginated too, not just in the ordinary case (layout regression)', () => {
240	    // `root.maxWidth` is a plain, unconditional value in the recipe — not gated behind
241	    // `isPaginated` the way `swatches.width`/`minWidth` deliberately are. This guards against a
242	    // plausible future slip: the reserved-width constant now backs both a paginated-only usage
243	    // (`swatches`) and this unconditional one (`root`), so a later edit that "tidies up" by moving
244	    // `root.maxWidth` inside the same `isPaginated` conditional as `swatches` would silently bring
245	    // the original bug back for every non-paginated case.
246	    const sixColours: ZimmColourSwatchValue[] = [
247	      BAY_BLUE,
248	      IVORY,
249	      BLACK,
250	      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
251	      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
252	      { value: 'NAVY', name: 'Navy', href: '/p.html?color=NAVY', imageUrl: IMAGE('navy') },
253	    ];
254	    renderGroup({ selectedName: BAY_BLUE.name, selectedValue: BAY_BLUE.value, values: sixColours });
255	    expect(screen.getAllByRole('radio')).toHaveLength(4); // paginated: isPaginated === true here
256	
257	    const rootStyles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
258	    const PAGE_SIZE = 4;
259	    const expectedMaxWidth = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;
260	    expect(rootStyles.maxWidth).toBe(expectedMaxWidth);
261	  });
262	
263	  test('truncates a long selected colour name, and only the dynamic name — never the static "Colour:" label', () => {
264	    // 70 characters — well past anything the labelName column could render on one line, so this
265	    // is a real exercise of the Figma interaction annotation ("If Label/Colour name is longer,
266	    // use truncation"), not just a token-presence check.
267	    const LONG_NAME = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
268	    expect(LONG_NAME.length).toBeGreaterThan(60);
269	
270	    renderGroup({ selectedName: LONG_NAME, selectedValue: 'BAYBL' });
271	
272	    const dynamicNameStyles = window.getComputedStyle(screen.getByText(LONG_NAME));
273	    expect(dynamicNameStyles.overflow).toBe('hidden');
274	    expect(dynamicNameStyles.textOverflow).toBe('ellipsis');
275	    expect(dynamicNameStyles.whiteSpace).toBe('nowrap');
276	
277	    // The static "Colour:" text beside it is never meant to truncate — only the dynamic name
278	    // carries the Figma-mandated behaviour above.
279	    const staticLabelStyles = window.getComputedStyle(screen.getByText('Colour:'));
280	    expect(staticLabelStyles.textOverflow).not.toBe('ellipsis');
281	  });
